function hemeGuide(){return '<section style="padding:11px;background:#f4f9ff;border:1px solid #d3e1f0;border-radius:10px"><b>Heme-positive urine: locate the pigment</b><div style="overflow:auto"><table style="width:100%;font-size:12px"><tr><th>Cause</th><th>Urine</th><th>Blood/chemistry</th></tr>'+[['Hematuria','RBC sediment and often red pellet','No hemoglobinemia expected'],['Hemoglobinuria','Pigmented supernatant; few RBC','Intravascular hemolysis: anemia and red plasma'],['Myoglobinuria','Pigmented supernatant; few RBC','Muscle necrosis; greatly increased CK'],['Urine RBC lysis','Ghost cells / no visible RBC','May have normal blood; check old, dilute or alkaline urine']].map(row=>'<tr>'+row.map(v=>'<td style="padding:5px;border-bottom:1px solid #d9e4f1">'+safe(v)+'</td>').join('')+'</tr>').join('')+'</table></div><p>The dipstick measures heme; it cannot distinguish these causes. Oxidized hemoglobin (methemoglobin) is brown, so color alone cannot identify myoglobin. Check urine centrifugation, plasma, HCT, CK, pH, USG, sample age and signs.</p><a href="https://eclinpath.com/urinalysis/chemical-constituents/" target="_blank" rel="noopener noreferrer">Cornell eClinPath heme guide</a></section>'}
function realPhoto(e,hideAnswer=false){
 const official=window.VPQ_ATLAS_PUBLISHER?.get?.(e.id);
 const builtIn=authenticPhotos[e.id];
 const officialPhotos=Array.isArray(official?.photos)?official.photos.filter(x=>/^https:\/\//i.test(x?.url||'')):[];
 const verified=officialPhotos.length?officialPhotos.map(x=>[x.url,x.source||builtIn?.[1]||'',x.credit||'Source attribution required']):builtIn?[builtIn]:[];
 const draft=(!hideAnswer&&window.VPQ_ATLAS_EDITOR?.read?.()[e.id])||null;
 const hasLocalDraft=Array.isArray(draft?.photos)&&draft.photos.some(x=>x?.url||x?.dataUrl);
 if(verified.length){
  return verified.map((p,i)=>'<figure style="margin:5px 0 13px;padding:10px;background:#f1f5fc;border:1px solid #d3deea;border-radius:13px;text-align:center"><img src="'+safe(p[0])+'" alt="Unlabeled authentic veterinary microscopic field" loading="lazy" style="width:100%;max-height:355px;object-fit:contain;border-radius:10px" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><p hidden>Image not available. <a href="'+safe(p[1])+'" target="_blank" rel="noopener noreferrer">Open original source</a></p><figcaption style="font-size:11px;color:#5f738b;margin-top:6px">Photo '+(i+1)+': '+(hideAnswer?'Unlabeled field':safe(p[2]))+' · <a href="'+safe(p[1])+'" target="_blank" rel="noopener noreferrer">Original photo / credit</a></figcaption></figure>').join('')+
  (hasLocalDraft?'<p style="font-size:12px;padding:8px;background:#fff7d6;border:1px solid #d0af65;border-radius:8px">✏️ You also have a saved private draft. Select <b>Edit this finding</b> to view or publish it. The official photo is displayed above.</p>':'');
 }
 const photos=Array.isArray(draft?.photos)?draft.photos:[];
 const selected=photos.filter(x=>/^https:\/\//i.test(x?.url||'')||/^data:image\/jpeg;base64,/i.test(x?.dataUrl||'')).slice(0,2);
 if(selected.length&&!hideAnswer)return '<div style="background:#fff7d6;border:1px solid #d0af65;border-radius:10px;padding:9px;margin:5px 0"><b>✏️ Personal draft preview — not published</b><p style="font-size:12px">Only this browser shows these previews.</p>'+
 selected.map(x=>'<figure style="margin:8px 0"><img alt="Draft atlas finding" src="'+safe(x.dataUrl||x.url)+'" loading="lazy" style="max-width:100%;max-height:320px;object-fit:contain"><figcaption style="font-size:11px">'+safe(x.credit||'Credit to be added before publishing')+'</figcaption></figure>').join('')+'</div>';
 return draw(e)+'<p style="font-size:11px">Teaching illustration only; authentic photo source is linked below.</p>';
}
