function optionsFor(e){
 const pool=entries.filter(x=>x.group===e.group&&x.id!==e.id);
 const broader=entries.filter(x=>x.group!==e.group&&!pool.some(p=>p.id===x.id));
 const distract=[...pool,...broader].slice(0,3).map(x=>({id:x.id,name:x.name}));
 const opts=[{id:e.id,name:e.name},...distract];
 const shift=(e.id.length*3)%4;
 return opts.slice(shift).concat(opts.slice(0,shift));
}
